   297	    private Map<String, Path> validateSelectedTags(Collection<String> jspTags, Path normalizedJspRoot) {
   298	        Map<String, Path> selected = new TreeMap<>();
   299	        for (String jspTag : jspTags) {
   300	            if (jspTag == null || jspTag.trim().isEmpty()) {
   301	                throw new IllegalArgumentException("JSP tag paths must not be null or blank.");
   302	            }
   303	
   304	            final Path relativePath;
   305	            try {
   306	                relativePath = Paths.get(jspTag);
   307	            } catch (InvalidPathException e) {
   308	                throw new IllegalArgumentException("Invalid JSP tag path: " + jspTag, e);
   309	            }
   310	            if (relativePath.isAbsolute()) {
   311	                throw new IllegalArgumentException("JSP tag paths must be root-relative: " + jspTag);
   312	            }
   313	
   314	            Path normalizedRelativePath = relativePath.normalize();
   315	            String normalizedName = normalizedRelativePath.toString().replace('\\', '/');
   316	            Path selectedPath = normalizedJspRoot.resolve(normalizedRelativePath).normalize();
   317	            if (normalizedName.isEmpty() || !selectedPath.startsWith(normalizedJspRoot)) {
   318	                throw new IllegalArgumentException("JSP tag path is outside the JSP root: " + jspTag);
   319	            }
   320	            if (!normalizedName.endsWith(".tag")) {
   321	                throw new IllegalArgumentException("JSP tag path must end in .tag: " + jspTag);
   322	            }
   323	            if (selected.put(normalizedName, selectedPath) != null) {
   324	                throw new IllegalArgumentException("Duplicate JSP tag path: " + jspTag);
   325	            }
   326	            if (Files.isSymbolicLink(selectedPath)) {
   327	                throw new IllegalArgumentException("Selected JSP tag must not be a symbolic link: " + selectedPath);
   328	            }
   329	            if (!Files.isRegularFile(selectedPath, LinkOption.NOFOLLOW_LINKS)) {
   330	                throw new IllegalArgumentException("Selected JSP tag is missing or not a regular file: " + selectedPath);
   331	            }
   332	            try {
   333	                if (!selectedPath.toRealPath().startsWith(normalizedJspRoot.toRealPath())) {
   334	                    throw new IllegalArgumentException("JSP tag path is outside the JSP root: " + jspTag);
   335	                }
   336	            } catch (IOException e) {
   337	                throw new IllegalArgumentException("Failed to resolve selected JSP tag: " + selectedPath, e);
   338	            }
   339	        }
   340	        return selected;
   341	    }
