   452	    private Path resolveInclude(URL resourceBase, String include, Path normalizedJspRoot) {
   453	        try {
   454	            if (!"file".equalsIgnoreCase(resourceBase.getProtocol())) {
   455	                throw new IllegalArgumentException("The converter resource base must be a file URL when planning migrations: " + resourceBase);
   456	            }
   457	            Path base = Paths.get(resourceBase.toURI()).toAbsolutePath().normalize();
   458	            String relativeInclude = include.startsWith("/") ? include.substring(1) : include;
   459	            Path resolved = base.resolve(relativeInclude).normalize();
   460	            if (!resolved.startsWith(normalizedJspRoot)) {
   461	                throw new IllegalArgumentException("Approved include is outside the JSP root: " + include);
   462	            }
   463	            if (Files.exists(resolved) && !resolved.toRealPath().startsWith(normalizedJspRoot.toRealPath())) {
   464	                throw new IllegalArgumentException("Approved include is outside the JSP root: " + include);
   465	            }
   466	            return resolved;
   467	        } catch (URISyntaxException | InvalidPathException | IOException e) {
   468	            throw new IllegalArgumentException("Invalid approved include path: " + include, e);
   469	        }
   470	    }
