   472	    private List<String> conversionOrder(Map<String, Set<String>> dependencies) {
   473	        Set<String> remaining = new TreeSet<>(dependencies.keySet());
   474	        List<String> result = new ArrayList<>();
   475	        while (!remaining.isEmpty()) {
   476	            String ready = null;
   477	            for (String candidate : remaining) {
   478	                if (Collections.disjoint(dependencies.get(candidate), remaining)) {
   479	                    ready = candidate;
   480	                    break;
   481	                }
   482	            }
   483	            if (ready == null) {
   484	                throw new IllegalArgumentException("JSP tag dependency cycle: " + String.join(" -> ", findCycle(remaining, dependencies)));
   485	            }
   486	            remaining.remove(ready);
   487	            result.add(ready);
   488	        }
   489	        return result;
   490	    }
