   492	    private List<String> findCycle(Set<String> remaining, Map<String, Set<String>> dependencies) {
   493	        Map<String, Integer> positions = new LinkedHashMap<>();
   494	        List<String> path = new ArrayList<>();
   495	        String current = remaining.iterator().next();
   496	        while (!positions.containsKey(current)) {
   497	            positions.put(current, path.size());
   498	            path.add(current);
   499	            current = dependencies.get(current).stream().filter(remaining::contains).findFirst().orElseThrow(IllegalStateException::new);
   500	        }
   501	        List<String> cycle = new ArrayList<>(path.subList(positions.get(current), path.size()));
   502	        cycle.add(current);
   503	        return cycle;
   504	    }
